import urls from '../../../../config/urls'
const configUrl = urls.url

export const APPROVAL_TASK = {
  GET_APPROVAL_DATA: 'GET_APPROVAL_DATA',
  GET_APPROVAL_DATA_REQUEST: 'GET_APPROVAL_DATA_REQUEST',

  CREATE_APPROVAL_DATA: 'CREATE_APPROVAL_DATA',
  CREATE_APPROVAL_DATA_REQUEST: 'CREATE_APPROVAL_DATA_REQUEST',

  APPROVE_APPROVAL_DATA: 'APPROVE_APPROVAL_DATA',
  APPROVE_APPROVAL_DATA_REQUEST: 'APPROVE_APPROVAL_DATA_REQUEST',

  REJECT_APPROVAL_DATA: 'REJECT_APPROVAL_DATA',
  REJECT_APPROVAL_DATA_REQUEST: 'REJECT_APPROVAL_DATA_REQUEST',

  CHANGE_PHONE_NUMBER: 'CHANGE_PHONE_NUMBER',
  CHANGE_PHONE_NUMBER_REQUEST: 'CHANGE_PHONE_NUMBER_REQUEST',

  RESET_REDUX_STATE_APPROVAL: 'RESET_REDUX_STATE_APPROVAL',

  getApprovalData: (payload) => ({
    type: APPROVAL_TASK.GET_APPROVAL_DATA_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getApprovalList
    }
  }),

  createApprovalData: (payload) => ({
    type: APPROVAL_TASK.CREATE_APPROVAL_DATA_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.createApprovalList
    }
  }),

  approveApprovalData: (payload) => ({
    type: APPROVAL_TASK.APPROVE_APPROVAL_DATA_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.approveApprovalList
    }
  }),

  rejectApprovalData: (payload) => ({
    type: APPROVAL_TASK.REJECT_APPROVAL_DATA_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.rejectApprovalList
    }
  }),

  changeUserPhone: (payload) => ({
    type: APPROVAL_TASK.CHANGE_PHONE_NUMBER_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.changeUserPhone
    }
  }),

  resetReduxStateApproval: (keys) => ({
    type: APPROVAL_TASK.RESET_REDUX_STATE_APPROVAL,
    payload: keys
  })
}
