import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const ApprovalContext = createContext()

export const ApprovalContextProvider = (props) => {
  return (
    <ApprovalContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </ApprovalContext.Provider>
  )
}

export const useApprovalContextValue = () => useContext(ApprovalContext)
