/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState, useCallback } from 'react'
import {
  Row,
  Icon,
  Col,
  Tag,
  notification,
  Spin,
  Button,
  message
} from 'antd'
import QueryString from 'query-string'
import moment from 'moment-timezone'
import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import { FilterInput } from '../../../../../components/tables/helperCells'
import ApprovalListWrapper from '../ApprovalList/style'
import TableWrapper from '../../pagination.style'
import {
  useGetApprovalData,
  useResetState
} from '../../state/hooks/useApprovalTaskContext'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import { imgIcon } from '../../constant.js'
const { copyToClipBoard } = imgIcon

const ApprovedList = ({ location, history, match }) => {
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  const [filterActive, setFilterActive] = useState(false)

  const [{ getApprovalDataData = {} }, getApprovalDataRequest] = useGetApprovalData()
  const [{ GET_APPROVAL_DATA_LOADER }] = useLoaderContextValue()
  const [resetState] = useResetState()

  const [
    {
      GET_APPROVAL_DATA_ERROR,
      getApprovalDataStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    fetch(querySearch)
    if (querySearch.sort) {
      delete querySearch.sort
    }
    setSearchTextQuery({ ...querySearch })
    setAppliedFilter({ ...querySearch })

    return () => resetState(['getApprovalDataData'])
  }, [])

  useEffect(() => {
    if (GET_APPROVAL_DATA_ERROR) {
      getApprovalDataStatus &&
        notification.error({ message: getApprovalDataStatus })
      dispatchError(
        resetError({
          GET_APPROVAL_DATA_ERROR: false,
          getApprovalDataStatus: ''
        })
      )
    }
  }, [GET_APPROVAL_DATA_ERROR])

  const fetch = useCallback((params = {}) => {
    const { page } = params
    const pageNumber = Number(page) || 1
    delete params.page

    getApprovalDataRequest({
      query: {
        ...params,
        page_number: pageNumber,
        request_status: 'SUCCESS'
      }
    })
  }, [])

  const renderWithClipBoard = (data) => {
    return (
      <div className='with-clipboard'>
        <p>{data}</p>
        <img
          src={copyToClipBoard}
          alt='clip-icon'
          onClick={() => {
            navigator.clipboard.writeText(data)
            message.success('Copied')
          }}
        />
      </div>
    )
  }

  const clearQuerySearchBuilder = useCallback(
    (identifier) => {
      const oldSearch = QueryString.parse(location?.search)
      delete oldSearch[identifier]
      const search = QuerySearchBuilder(oldSearch)
      history.push({ pathname: location?.pathname, search })
      return oldSearch
    },
    [location]
  )

  const renderTitle = useCallback((titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }, [])

  const onInputChange = useCallback(
    (value, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: value
      })
    },
    [searchTextQuery, setSearchTextQuery]
  )

  const onSearch = useCallback(
    (e, key) => {
      e.preventDefault()

      const searchText = { ...searchTextQuery, page: 1 }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
      setFilterActive({ ...filterActive, [key]: false })
      setAppliedFilter(searchTextQuery)
    },
    [searchTextQuery, filterActive]
  )

  const clearFilter = useCallback(
    (identifier) => {
      const searchText = {
        ...searchTextQuery,
        [identifier]: undefined
      }
      setSearchTextQuery(searchText)
      setAppliedFilter(searchText)

      const oldSearch = clearQuerySearchBuilder(identifier)
      fetch(oldSearch)
    },
    [
      searchTextQuery,
      clearQuerySearchBuilder,
      setAppliedFilter,
      setSearchTextQuery
    ]
  )

  const handlePolicyDetail = (data) => {
    const internalId = data?.request_payload?.response?.internal_ids[0]
    if (internalId) {
      history.push(`/policy/${internalId}`)
    }
  }

  const columns = [
    {
      key: 'ticket_id',
      title: renderTitle('title-with-margin', 'Zoho Ticket ID'),
      dataIndex: 'ticket_id',
      className: 'title',
      render: (data) => renderWithClipBoard(data),
      filterDropdown: (
        <FilterInput
          idIdentifier='ticket_id'
          searchText={
            searchTextQuery.ticket_id ? searchTextQuery.ticket_id : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, 'ticket_id')}
          onSearch={(e) => onSearch(e, 'ticket_id')}
        />
      ),
      filterIcon: (
        <Icon type='filter' theme='outlined' className='filter-icon' />
      ),
      filterDropdownVisible: filterActive?.ticket_id,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, ticket_id: visible })
    },
    {
      key: 'action',
      title: renderTitle('title-with-margin', 'Request Type'),
      dataIndex: 'action',
      filterDropdown: (
        <FilterInput
          idIdentifier='action'
          searchText={
            searchTextQuery.action ? searchTextQuery.action : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, 'action')}
          onSearch={(e) => onSearch(e, 'action')}
        />
      ),
      filterIcon: (
        <Icon type='filter' theme='outlined' className='filter-icon' />
      ),
      filterDropdownVisible: filterActive?.action,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, action: visible })
    },
    {
      key: 'created_at',
      title: 'Requested At',
      dataIndex: 'created_at',
      render: (date) => moment(date).tz('Asia/Jakarta').format('lll')
    },
    {
      key: 'requested_by',
      title: 'Requested By',
      dataIndex: 'requested_by'
    },
    {
      key: 'identifier',
      title: renderTitle('title-with-margin', 'Application Number'),
      render: (data) => <span className='blue pointer' onClick={() => handlePolicyDetail(data)} >{data?.identifier}</span>,
      filterDropdown: (
        <FilterInput
          idIdentifier='identifier'
          searchText={
            searchTextQuery.identifier
              ? searchTextQuery.identifier
              : undefined
          }
          onInputChange={(e) =>
            onInputChange(e.target.value, 'identifier')}
          onSearch={(e) => onSearch(e, 'identifier')}
        />
      ),
      filterIcon: (
        <Icon type='filter' theme='outlined' className='filter-icon' />
      ),
      filterDropdownVisible: filterActive?.identifier,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, identifier: visible })
    },
    {
      key: 'approved_by',
      title: 'Decided By',
      dataIndex: 'approved_by'
    },
    {
      key: 'approval_status',
      title: 'Decision',
      dataIndex: 'approval_status',
      render: (data) => (
        <p className={data === 'APPROVED' ? 'green' : 'red'}>{data}</p>
      )
    }
  ]

  const handlePageChange = useCallback(
    (pagination, filters, sorter) => {
      const { current } = pagination
      const querySearch = QueryString.parse(location?.search)
      const searchText = { ...querySearch, page: current }
      if (sorter?.field === 'reference_id' && sorter?.order === 'descend') {
        searchText.sort = 'desc'
      } else if (sorter?.field === 'reference_id' && sorter?.order === 'ascend') {
        searchText.sort = 'asc'
      } else {
        searchText.sort = undefined
      }

      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
    },
    [QueryString, location]
  )

  return (
    <LayoutContentWrapper>
      <ApprovalListWrapper>
        <Spin spinning={GET_APPROVAL_DATA_LOADER}>
          <Row type='flex' align='middle'>
            <Col sm={4} md={8}>
              <div className='heading'>
                <h3>
                  <b>Approval Task</b>
                </h3>
              </div>
            </Col>
          </Row>
          <div className='approval__button'>
            <div className='approval__buttonToggle'>
              <Button
                onClick={() =>
                  history.replace('/customer-support/approval-task')}
              >
                <b>New</b>
              </Button>
              <Button
                onClick={() =>
                  history.replace('/customer-support/approval-task/approved')}
                disabled
                className='btn-blue'
              >
                <b>Done</b>
              </Button>
            </div>
          </div>
          {appliedFilter &&
            Object.keys(appliedFilter).map((key, index) => {
              if (appliedFilter[key]) {
                return (
                  <Tag key={index} className='filter-tag' color='geekblue'>
                    {appliedFilter[key]}
                    <span
                      className='remove-filter'
                      onClick={(e) => clearFilter(key)}
                    >
                      <Icon type='close' className='close' />
                    </span>
                  </Tag>
                )
              } else {
                return ''
              }
            })}

          <TableWrapper
            columns={columns}
            rowKey={(record) => record.id}
            dataSource={getApprovalDataData?.data}
            pagination={{
              pageSize: 10,
              total: Number(getApprovalDataData?.metadata?.total_count),
              current: getApprovalDataData?.metadata?.page_number
            }}
            className='isoSearchableTable'
            onChange={handlePageChange}
          />
        </Spin>
      </ApprovalListWrapper>
    </LayoutContentWrapper>
  )
}

export default ApprovedList
