import { APPROVAL_TASK } from './actions'

export const INITIAL_STATE = { }

const reducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case APPROVAL_TASK.GET_APPROVAL_DATA:
    case APPROVAL_TASK.CREATE_APPROVAL_DATA:
    case APPROVAL_TASK.APPROVE_APPROVAL_DATA:
    case APPROVAL_TASK.REJECT_APPROVAL_DATA:
      return { ...state, ...payload }
    case APPROVAL_TASK.RESET_REDUX_STATE_APPROVAL:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducer
