import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useApprovalContextValue } from '../../context'
import { APPROVAL_TASK } from '../actions'

export const useApprovalServiceCall = (actionsCall = () => {}) => {
  const [approvalState, dispatch] = useApprovalContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(
      actionsCall({
        ...payload
      })
    )
  }

  return [approvalState, request]
}

export const useGetApprovalData = () => {
  return useApprovalServiceCall(APPROVAL_TASK.getApprovalData)
}

export const useCreateApprovalData = () => {
  return useApprovalServiceCall(APPROVAL_TASK.createApprovalData)
}

export const useApproveApprovalData = () => {
  return useApprovalServiceCall(APPROVAL_TASK.approveApprovalData)
}

export const useRejectApprovalData = () => {
  return useApprovalServiceCall(APPROVAL_TASK.rejectApprovalData)
}

export const useResetState = () => {
  const [, dispatch] = useApprovalContextValue()
  const resetState = (keys = []) => {
    dispatch(APPROVAL_TASK.resetReduxStateApproval(keys))
  }
  return [resetState]
}
